// components/Layout.js
import React from 'react';
import Link from 'next/link';
import { 
  Dashboard as DashboardIcon,
  People as PeopleIcon,
  Group as GroupIcon,
  Event as EventIcon,
  Feedback as FeedbackIcon,
  Settings as SettingsIcon,
  ExitToApp as LogoutIcon
} from '@mui/icons-material';

export default function Layout({ children, title }) {
  return (
    <div className="app-container">
      <div className="sidebar">
        <div className="logo-container">
          <img src="/logo.png" alt="SAFI" className="logo" />
        </div>
        
        <ul className="sidebar-menu">
          <li>
            <Link href="/dashboard" className={title === "Dashboard" ? "active" : ""}>
              <DashboardIcon className="icon" />
              Dashboard
            </Link>
          </li>
          <li>
            <Link href="/conseillers" className={title === "Liste des Conseillers" ? "active" : ""}>
              <PeopleIcon className="icon" />
              Conseillers
            </Link>
          </li>
          <li>
            <Link href="/etudiants" className={title === "Liste des étudiants" ? "active" : ""}>
              <GroupIcon className="icon" />
              Étudiants
            </Link>
          </li>
          <li>
            <Link href="/collaborateurs" className={title === "Liste des Collaborateurs" ? "active" : ""}>
              <GroupIcon className="icon" />
              Collaborateurs
            </Link>
          </li>
          <li>
            <Link href="/evenements" className={title === "Événements" ? "active" : ""}>
              <EventIcon className="icon" />
              Événements
            </Link>
          </li>
          <li>
            <Link href="/feedback" className={title === "Feedback" ? "active" : ""}>
              <FeedbackIcon className="icon" />
              Feedback
            </Link>
          </li>
          <li>
            <Link href="/parametres" className={title === "Paramètres" ? "active" : ""}>
              <SettingsIcon className="icon" />
              Paramètres
            </Link>
          </li>
          <li>
            <Link href="/logout">
              <LogoutIcon className="icon" />
              Déconnexion
            </Link>
          </li>
        </ul>
      </div>
      
      <div className="main-content">
        <div className="page-header">
          <h1 className="page-title">{title}</h1>
        </div>
        
        {children}
      </div>
    </div>
  );
} 
